// decrease the size of the tenant group's data.
func (o TransactionOptions) SetBypassStorageQuota() error {
	return o.t.setOption(options.TransactionBypassStorageQuota, nil)
}

// SetDebugRetryLogging sets the debug_retry_logging option.
// Parameter: Optional transaction name
func (o TransactionOptions) SetDebugRetryLogging(param string) error {
	return o.t.setOption(options.TransactionDebugRetryLogging, []byte(param))
}

// SetDebugTransactionIdentifier sets the debug_transaction_identifier option. Sets a client
// provided identifier for the transaction that will be used in scenarios like tracing or profiling.
// Client trace logging or transaction profiling must be separately enabled.
// Parameter: String identifier to be used when tracing or profiling this transaction. The
// identifier must not exceed 100 characters.
func (o TransactionOptions) SetDebugTransactionIdentifier(param string) error {
	return o.t.setOption(options.TransactionDebugTransactionIdentifier, []byte(param))
}

// SetLogTransaction sets the log_transaction option. Enables tracing for this transaction and logs
// results to the client trace logs. The DEBUG_TRANSACTION_IDENTIFIER option must be set before
// using this option, and client trace logging must be enabled to get log output.
func (o TransactionOptions) SetLogTransaction() error {
	return o.t.setOption(options.TransactionLogTransaction, nil)
}

// SetTransactionLoggingMaxFieldLength sets the transaction_logging_max_field_length option. Sets
// the maximum escaped length of key and value fields to be logged to the trace file via the
// LOG_TRANSACTION option, after which the field will be truncated. A negative value disables
// truncation.
// Parameter: Maximum length of escaped key and value fields.
func (o TransactionOptions) SetTransactionLoggingMaxFieldLength(param int64) error {
	return o.t.setOption(options.TransactionTransactionLoggingMaxFieldLength, int64Param(param))
}

// SetServerRequestTracing sets the server_request_tracing option. Sets an identifier for server
// tracing of this transaction. When committed, this identifier triggers logging when each part of
// the transaction authority encounters it, which is helpful in diagnosing slowness in misbehaving
// clusters. The identifier is randomly generated. When there is also a
// debug_transaction_identifier, both IDs are logged together.
func (o TransactionOptions) SetServerRequestTracing() error {
	return o.t.setOption(options.TransactionServerRequestTracing, nil)
}

// SetTimeout sets the timeout option. Set a timeout in milliseconds which, when elapsed, will cause
// the transaction automatically to be cancelled. Valid parameter values are [0, INT_MAX]. If set to
// 0, will disable all timeouts. All pending and any future uses of the transaction will throw an
// exception. The transaction can be used again after it is reset. Prior to API version 610, like
// all other transaction options, the timeout must be reset after a call to onError. If the API
// version is 610 or greater, the timeout is not reset after an onError call. This allows the user
// to specify a longer timeout on specific transactions than the default timeout specified through
// the transaction_timeout database option without the shorter database timeout cancelling
// transactions that encounter a retryable error. Note that at all API versions, it is safe and
// legal to set the timeout each time the transaction begins, so most code written assuming the
// older behavior can be upgraded to the newer behavior without requiring any modification, and the
// caller is not required to implement special logic in retry loops to only conditionally set this
// option.
// Parameter: value in milliseconds of timeout
func (o TransactionOptions) SetTimeout(param int64) error {
	return o.t.setOption(options.TransactionTimeout, int64Param(param))
}

// SetRetryLimit sets the retry_limit option. Set a maximum number of retries after which additional
// calls to onError will throw the most recently seen error code. Valid parameter values are [-1,
// INT_MAX]. If set to -1, will disable the retry limit. Prior to API version 610, like all other
// transaction options, the retry limit must be reset after a call to onError. If the API version is
// 610 or greater, the retry limit is not reset after an onError call. Note that at all API
// versions, it is safe and legal to set the retry limit each time the transaction begins, so most
// code written assuming the older behavior can be upgraded to the newer behavior without requiring
// any modification, and the caller is not required to implement special logic in retry loops to
// only conditionally set this option.
// Parameter: number of times to retry
func (o TransactionOptions) SetRetryLimit(param int64) error {
	return o.t.setOption(options.TransactionRetryLimit, int64Param(param))
}

// SetMaxRetryDelay sets the max_retry_delay option. Set the maximum amount of backoff delay
// incurred in the call to onError if the error is retryable. Defaults to 1000 ms. Valid parameter
// values are [0, INT_MAX]. If the maximum retry delay is less than the current retry delay of the
// transaction, then the current retry delay will be clamped to the maximum retry delay. Prior to
// API version 610, like all other transaction options, the maximum retry delay must be reset after
// a call to onError. If the API version is 610 or greater, the retry limit is not reset after an
// onError call. Note that at all API versions, it is safe and legal to set the maximum retry delay
// each time the transaction begins, so most code written assuming the older behavior can be
// upgraded to the newer behavior without requiring any modification, and the caller is not required
// to implement special logic in retry loops to only conditionally set this option.
// Parameter: value in milliseconds of maximum delay
func (o TransactionOptions) SetMaxRetryDelay(param int64) error {
	return o.t.setOption(options.TransactionMaxRetryDelay, int64Param(param))
}

// SetSizeLimit sets the size_limit option. Set the transaction size limit in bytes. The size is
// calculated by combining the sizes of all keys and values written or mutated, all key ranges
// cleared, and all read and write conflict ranges. (In other words, it includes the total size of
// all data included in the request to the cluster to commit the transaction.) Large transactions
// can cause performance problems on FoundationDB clusters, so setting this limit to a smaller value
// than the default can help prevent the client from accidentally degrading the cluster's
// performance. This value must be at least 32 and cannot be set to higher than 10,000,000, the
// default transaction size limit.
// Parameter: value in bytes
func (o TransactionOptions) SetSizeLimit(param int64) error {
	return o.t.setOption(options.TransactionSizeLimit, int64Param(param))
}

// SetAutomaticIdempotency sets the automatic_idempotency option. Automatically assign a random 16
// byte idempotency id for this transaction. Prevents commits from failing with
// commit_unknown_result. WARNING: If you are also using the multiversion client or transaction
// timeouts, if either cluster_version_changed or transaction_timed_out was thrown during a commit,
// then that commit may have already succeeded or may succeed in the future. This feature is in
// development and not ready for general use.
func (o TransactionOptions) SetAutomaticIdempotency() error {
	return o.t.setOption(options.TransactionAutomaticIdempotency, nil)
}

// SetSnapshotRYWEnable sets the snapshot_ryw_enable option. Snapshot read operations will see the
// results of writes done in the same transaction. This is the default behavior.
func (o TransactionOptions) SetSnapshotRYWEnable() error {
	return o.t.setOption(options.TransactionSnapshotRYWEnable, nil)
}

// SetSnapshotRYWDisable sets the snapshot_ryw_disable option. Snapshot read operations will not see
// the results of writes done in the same transaction. This was the default behavior prior to API
// version 300.
func (o TransactionOptions) SetSnapshotRYWDisable() error {
	return o.t.setOption(options.TransactionSnapshotRYWDisable, nil)
}

// SetLockAware sets the lock_aware option. The transaction can read and write to locked databases,
// and is responsible for checking that it took the lock.
func (o TransactionOptions) SetLockAware() error {
	return o.t.setOption(options.TransactionLockAware, nil)
}

// SetUsedDuringCommitProtectionDisable sets the used_during_commit_protection_disable option. By
// default, operations that are performed on a transaction while it is being committed will not only
// fail themselves, but they will attempt to fail other in-flight operations (such as the commit) as
// well. This behavior is intended to help developers discover situations where operations could be
// unintentionally executed after the transaction has been reset. Setting this option removes that
// protection, causing only the offending operation to fail.
func (o TransactionOptions) SetUsedDuringCommitProtectionDisable() error {
	return o.t.setOption(options.TransactionUsedDuringCommitProtectionDisable, nil)
}

// SetReadLockAware sets the read_lock_aware option. The transaction can read from locked databases.
func (o TransactionOptions) SetReadLockAware() error {
	return o.t.setOption(options.TransactionReadLockAware, nil)
}

// SetUseProvisionalProxies sets the use_provisional_proxies option. This option should only be used
// by tools which change the database configuration.
func (o TransactionOptions) SetUseProvisionalProxies() error {
	return o.t.setOption(options.TransactionUseProvisionalProxies, nil)
}

// SetReportConflictingKeys sets the report_conflicting_keys option. The transaction can retrieve
// keys that are conflicting with other transactions.
func (o TransactionOptions) SetReportConflictingKeys() error {
	return o.t.setOption(options.TransactionReportConflictingKeys, nil)
}

// SetSpecialKeySpaceRelaxed sets the special_key_space_relaxed option. By default, the special key
// space will only allow users to read from exactly one module (a subspace in the special key
// space). Use this option to allow reading from zero or more modules. Users who set this option
// should be prepared for new modules, which may have different behaviors than the modules they're
// currently reading. For example, a new module might block or return an error.
func (o TransactionOptions) SetSpecialKeySpaceRelaxed() error {
	return o.t.setOption(options.TransactionSpecialKeySpaceRelaxed, nil)
}

// SetSpecialKeySpaceEnableWrites sets the special_key_space_enable_writes option. By default, users
// are not allowed to write to special keys. Enable this option will implicitly enable all options
// required to achieve the configuration change.
func (o TransactionOptions) SetSpecialKeySpaceEnableWrites() error {
	return o.t.setOption(options.TransactionSpecialKeySpaceEnableWrites, nil)
}

// SetTag sets the tag option. Adds a tag to the transaction that can be used to apply manual
// targeted throttling. At most 5 tags can be set on a transaction.
// Parameter: String identifier used to associated this transaction with a throttling group. Must
// not exceed 16 characters.
func (o TransactionOptions) SetTag(param string) error {
	return o.t.setOption(options.TransactionTag, []byte(param))
}

// SetAutoThrottleTag sets the auto_throttle_tag option. Adds a tag to the transaction that can be
// used to apply manual or automatic targeted throttling. At most 5 tags can be set on a
// transaction.
// Parameter: String identifier used to associated this transaction with a throttling group. Must
// not exceed 16 characters.
func (o TransactionOptions) SetAutoThrottleTag(param string) error {
	return o.t.setOption(options.TransactionAutoThrottleTag, []byte(param))
}

// SetSpanParent sets the span_parent option. Adds a parent to the Span of this transaction. Used
// for transaction tracing. A span can be identified with a 33 bytes serialized binary format which
// consists of: 8 bytes protocol version, e.g. 0x0FDB00B073000000LL in little-endian format, 16
// bytes trace id, 8 bytes span id, 1 byte set to 1 if sampling is enabled
