// transaction with a parent
func (o TransactionOptions) SetSpanParent(param []byte) error {
	return o.t.setOption(options.TransactionSpanParent, param)
}

// SetExpensiveClearCostEstimationEnable sets the expensive_clear_cost_estimation_enable option.
// Asks storage servers for how many bytes a clear key range contains. Otherwise uses the location
// cache to roughly estimate this.
func (o TransactionOptions) SetExpensiveClearCostEstimationEnable() error {
	return o.t.setOption(options.TransactionExpensiveClearCostEstimationEnable, nil)
}

// SetBypassUnreadable sets the bypass_unreadable option. Allows get operations to read from
// sections of keyspace that have become unreadable because of versionstamp operations. These reads
// will view versionstamp operations as if they were set operations that did not fill in the
