func (o TransactionOptions) SetBypassUnreadable() error {
	return o.t.setOption(options.TransactionBypassUnreadable, nil)
}

// SetUseGRVCache sets the use_grv_cache option. Allows this transaction to use cached GRV from the
// database context. Defaults to off. Upon first usage, starts a background updater to periodically
