func (o TransactionOptions) SetUseGRVCache() error {
	return o.t.setOption(options.TransactionUseGRVCache, nil)
}

// SetAuthorizationToken sets the authorization_token option. Attach given authorization token to
// the transaction such that subsequent tenant-aware requests are authorized
// Parameter: A JSON Web Token authorized to access data belonging to one or more tenants, indicated
// by 'tenants' claim of the token's payload.
func (o TransactionOptions) SetAuthorizationToken(param string) error {
	return o.t.setOption(options.TransactionAuthorizationToken, []byte(param))
}

// SetEnableReplicaConsistencyCheck sets the enable_replica_consistency_check option. Enables
// replica consistency check, which compares the results returned by storage server replicas (as
// many as specified by consistency_check_required_replicas option) for a given read request, in
// client-side load balancer.
func (o TransactionOptions) SetEnableReplicaConsistencyCheck() error {
	return o.t.setOption(options.TransactionEnableReplicaConsistencyCheck, nil)
}

// SetConsistencyCheckRequiredReplicas sets the consistency_check_required_replicas option.
// Specifies the number of storage server replica results that the load balancer needs to compare
// when enable_replica_consistency_check option is set.
// Parameter: Number of storage replicas over which the load balancer consistency check is done.
func (o TransactionOptions) SetConsistencyCheckRequiredReplicas(param int64) error {
	return o.t.setOption(options.TransactionConsistencyCheckRequiredReplicas, int64Param(param))
}

// StreamingMode tunes how a range read is batched. Values are the C codes
// plus one, so the zero value is StreamingModeIterator.
type StreamingMode int

// Streaming modes.
const (
	// StreamingModeWantAll is the want_all streaming mode. Client intends to consume the entire
	// range and would like it all transferred as early as possible.
	StreamingModeWantAll StreamingMode = -1
	// StreamingModeIterator is the iterator streaming mode. The default. The client doesn't know
	// how much of the range it is likely to used and wants different performance concerns to be
	// balanced. Only a small portion of data is transferred to the client initially (in order to
	// minimize costs if the client doesn't read the entire range), and as the caller iterates over
	// more items in the range larger batches will be transferred in order to minimize latency.
	// After enough iterations, the iterator mode will eventually reach the same byte limit as
	// WANT_ALL
	StreamingModeIterator StreamingMode = 0
	// StreamingModeExact is the exact streaming mode. Infrequently used. The client has passed a
	// specific row limit and wants that many rows delivered in a single batch. Because of iterator
	// operation in client drivers make request batches transparent to the user, consider WANT_ALL
	// StreamingMode instead. A row limit must be specified if this mode is used.
	StreamingModeExact StreamingMode = 1
	// StreamingModeSmall is the small streaming mode. Infrequently used. Transfer data in batches
	// small enough to not be much more expensive than reading individual rows, to minimize cost if
	// iteration stops early.
	StreamingModeSmall StreamingMode = 2
	// StreamingModeMedium is the medium streaming mode. Infrequently used. Transfer data in batches
	// sized in between small and large.
	StreamingModeMedium StreamingMode = 3
	// StreamingModeLarge is the large streaming mode. Infrequently used. Transfer data in batches
	// large enough to be, in a high-concurrency environment, nearly as efficient as possible. If
	// the client stops iteration early, some disk and network bandwidth may be wasted. The batch
	// size may still be too small to allow a single client to get high throughput from the
	// database, so if that is what you need consider the SERIAL StreamingMode.
	StreamingModeLarge StreamingMode = 4
	// StreamingModeSerial is the serial streaming mode. Transfer data in batches large enough that
	// an individual client can get reasonable read bandwidth from the database. If the client stops
	// iteration early, considerable disk and network bandwidth may be wasted.
	StreamingModeSerial StreamingMode = 5
)

// MutationType is an atomic operation applied with Transaction.Atomic.
type MutationType int

// Mutation types.
const (
	// MutationTypeAdd is the add mutation type. Performs an addition of little-endian integers. If
	// the existing value in the database is not present or shorter than param, it is first extended
	// to the length of param with zero bytes. If param is shorter than the existing value in the
	// database, the existing value is truncated to match the length of param. The integers to be
	// added must be stored in a little-endian representation. They can be signed in two's
	// complement representation or unsigned. You can add to an integer at a known offset in the
	// value by prepending the appropriate number of zero bytes to param and padding with zero bytes
	// to match the length of the value. However, this offset technique requires that you know the
	// addition will not cause the integer field within the value to overflow.
	// Parameter: addend
	MutationTypeAdd MutationType = options.MutationTypeAdd
	// MutationTypeBitAnd is the bit_and mutation type. Performs a bitwise and operation. If the
	// existing value in the database is not present, then param is stored in the database. If the
	// existing value in the database is shorter than param, it is first extended to the length of
	// param with zero bytes. If param is shorter than the existing value in the database, the
	// existing value is truncated to match the length of param.
	// Parameter: value with which to perform bitwise and
	MutationTypeBitAnd MutationType = options.MutationTypeBitAnd
	// MutationTypeBitOr is the bit_or mutation type. Performs a bitwise or operation. If the
	// existing value in the database is not present or shorter than param, it is first extended to
	// the length of param with zero bytes. If param is shorter than the existing value in the
	// database, the existing value is truncated to match the length of param.
	// Parameter: value with which to perform bitwise or
	MutationTypeBitOr MutationType = options.MutationTypeBitOr
	// MutationTypeBitXor is the bit_xor mutation type. Performs a bitwise xor operation. If the
	// existing value in the database is not present or shorter than param, it is first extended to
	// the length of param with zero bytes. If param is shorter than the existing value in the
	// database, the existing value is truncated to match the length of param.
	// Parameter: value with which to perform bitwise xor
	MutationTypeBitXor MutationType = options.MutationTypeBitXor
	// MutationTypeAppendIfFits is the append_if_fits mutation type. Appends param to the end of the
	// existing value already in the database at the given key (or creates the key and sets the
	// value to param if the key is empty). This will only append the value if the final
	// concatenated value size is less than or equal to the maximum value size (i.e., if it fits).
	// WARNING: No error is surfaced back to the user if the final value is too large because the
	// mutation will not be applied until after the transaction has been committed. Therefore, it is
	// only safe to use this mutation type if one can guarantee that one will keep the total value
	// size under the maximum size.
	// Parameter: value to append to the database value
	MutationTypeAppendIfFits MutationType = options.MutationTypeAppendIfFits
	// MutationTypeMax is the max mutation type. Performs a little-endian comparison of byte
	// strings. If the existing value in the database is not present or shorter than param, it is
	// first extended to the length of param with zero bytes. If param is shorter than the existing
	// value in the database, the existing value is truncated to match the length of param. The
	// larger of the two values is then stored in the database.
	// Parameter: value to check against database value
	MutationTypeMax MutationType = options.MutationTypeMax
	// MutationTypeMin is the min mutation type. Performs a little-endian comparison of byte
	// strings. If the existing value in the database is not present, then param is stored in the
	// database. If the existing value in the database is shorter than param, it is first extended
	// to the length of param with zero bytes. If param is shorter than the existing value in the
	// database, the existing value is truncated to match the length of param. The smaller of the
	// two values is then stored in the database.
	// Parameter: value to check against database value
	MutationTypeMin MutationType = options.MutationTypeMin
	// MutationTypeSetVersionstampedKey is the set_versionstamped_key mutation type. Transforms key
	// using a versionstamp for the transaction. Sets the transformed key in the database to param.
	// The key is transformed by removing the final four bytes from the key and reading those as a
	// little-Endian 32-bit integer to get a position pos. The 10 bytes of the key from pos to pos +
	// 10 are replaced with the versionstamp of the transaction used. The first byte of the key is
	// position 0. A versionstamp is a 10 byte, unique, monotonically (but not sequentially)
	// increasing value for each committed transaction. The first 8 bytes are the committed version
	// of the database (serialized in big-Endian order). The last 2 bytes are monotonic in the
	// serialization order for transactions. WARNING: At this time, versionstamps are compatible
	// with the Tuple layer only in the Java, Python, and Go bindings. Also, note that prior to API
	// version 520, the offset was computed from only the final two bytes rather than the final four
	// bytes.
	// Parameter: value to which to set the transformed key
	MutationTypeSetVersionstampedKey MutationType = options.MutationTypeSetVersionstampedKey
	// MutationTypeSetVersionstampedValue is the set_versionstamped_value mutation type. Transforms
	// param using a versionstamp for the transaction. Sets the key given to the transformed param.
	// The parameter is transformed by removing the final four bytes from param and reading those as
	// a little-Endian 32-bit integer to get a position pos. The 10 bytes of the parameter from pos
	// to pos + 10 are replaced with the versionstamp of the transaction used. The first byte of the
	// parameter is position 0. A versionstamp is a 10 byte, unique, monotonically (but not
	// sequentially) increasing value for each committed transaction. The first 8 bytes are the
	// committed version of the database (serialized in big-Endian order). The last 2 bytes are
	// monotonic in the serialization order for transactions. WARNING: At this time, versionstamps
	// are compatible with the Tuple layer only in the Java, Python, and Go bindings. Also, note
	// that prior to API version 520, the versionstamp was always placed at the beginning of the
	// parameter rather than computing an offset.
	// Parameter: value to versionstamp and set
	MutationTypeSetVersionstampedValue MutationType = options.MutationTypeSetVersionstampedValue
	// MutationTypeByteMin is the byte_min mutation type. Performs lexicographic comparison of byte
	// strings. If the existing value in the database is not present, then param is stored.
	// Otherwise the smaller of the two values is then stored in the database.
	// Parameter: value to check against database value
	MutationTypeByteMin MutationType = options.MutationTypeByteMin
	// MutationTypeByteMax is the byte_max mutation type. Performs lexicographic comparison of byte
	// strings. If the existing value in the database is not present, then param is stored.
	// Otherwise the larger of the two values is then stored in the database.
	// Parameter: value to check against database value
	MutationTypeByteMax MutationType = options.MutationTypeByteMax
	// MutationTypeCompareAndClear is the compare_and_clear mutation type. Performs an atomic
	// compare and clear operation. If the existing value in the database is equal to the given
	// value, then given key is cleared.
	// Parameter: Value to compare with
	MutationTypeCompareAndClear MutationType = options.MutationTypeCompareAndClear
)

// Add applies the add mutation type to key. Performs an addition of little-endian integers. If the
// existing value in the database is not present or shorter than param, it is first extended to the
// length of param with zero bytes. If param is shorter than the existing value in the database, the
// existing value is truncated to match the length of param. The integers to be added must be stored
// in a little-endian representation. They can be signed in two's complement representation or
// unsigned. You can add to an integer at a known offset in the value by prepending the appropriate
// number of zero bytes to param and padding with zero bytes to match the length of the value.
// However, this offset technique requires that you know the addition will not cause the integer
// field within the value to overflow.
// Parameter: addend
func (t *Transaction) Add(key, param []byte) {
	t.Atomic(MutationTypeAdd, key, param)
}

// BitAnd applies the bit_and mutation type to key. Performs a bitwise and operation. If the
// existing value in the database is not present, then param is stored in the database. If the
// existing value in the database is shorter than param, it is first extended to the length of param
// with zero bytes. If param is shorter than the existing value in the database, the existing value
// is truncated to match the length of param.
// Parameter: value with which to perform bitwise and
func (t *Transaction) BitAnd(key, param []byte) {
	t.Atomic(MutationTypeBitAnd, key, param)
}

// BitOr applies the bit_or mutation type to key. Performs a bitwise or operation. If the existing
// value in the database is not present or shorter than param, it is first extended to the length of
// param with zero bytes. If param is shorter than the existing value in the database, the existing
// value is truncated to match the length of param.
// Parameter: value with which to perform bitwise or
func (t *Transaction) BitOr(key, param []byte) {
	t.Atomic(MutationTypeBitOr, key, param)
}

// BitXor applies the bit_xor mutation type to key. Performs a bitwise xor operation. If the
// existing value in the database is not present or shorter than param, it is first extended to the
// length of param with zero bytes. If param is shorter than the existing value in the database, the
// existing value is truncated to match the length of param.
// Parameter: value with which to perform bitwise xor
func (t *Transaction) BitXor(key, param []byte) {
	t.Atomic(MutationTypeBitXor, key, param)
}

// AppendIfFits applies the append_if_fits mutation type to key. Appends param to the end of the
// existing value already in the database at the given key (or creates the key and sets the value to
// param if the key is empty). This will only append the value if the final concatenated value size
// is less than or equal to the maximum value size (i.e., if it fits). WARNING: No error is surfaced
// back to the user if the final value is too large because the mutation will not be applied until
// after the transaction has been committed. Therefore, it is only safe to use this mutation type if
// one can guarantee that one will keep the total value size under the maximum size.
// Parameter: value to append to the database value
func (t *Transaction) AppendIfFits(key, param []byte) {
	t.Atomic(MutationTypeAppendIfFits, key, param)
}

// Max applies the max mutation type to key. Performs a little-endian comparison of byte strings. If
// the existing value in the database is not present or shorter than param, it is first extended to
// the length of param with zero bytes. If param is shorter than the existing value in the database,
// the existing value is truncated to match the length of param. The larger of the two values is
// then stored in the database.
// Parameter: value to check against database value
func (t *Transaction) Max(key, param []byte) {
	t.Atomic(MutationTypeMax, key, param)
}

// Min applies the min mutation type to key. Performs a little-endian comparison of byte strings. If
// the existing value in the database is not present, then param is stored in the database. If the
// existing value in the database is shorter than param, it is first extended to the length of param
// with zero bytes. If param is shorter than the existing value in the database, the existing value
// is truncated to match the length of param. The smaller of the two values is then stored in the
// database.
// Parameter: value to check against database value
func (t *Transaction) Min(key, param []byte) {
	t.Atomic(MutationTypeMin, key, param)
}

// SetVersionstampedKey applies the set_versionstamped_key mutation type to key. Transforms key
// using a versionstamp for the transaction. Sets the transformed key in the database to param. The
// key is transformed by removing the final four bytes from the key and reading those as a
// little-Endian 32-bit integer to get a position pos. The 10 bytes of the key from pos to pos + 10
// are replaced with the versionstamp of the transaction used. The first byte of the key is position
// 0. A versionstamp is a 10 byte, unique, monotonically (but not sequentially) increasing value for
// each committed transaction. The first 8 bytes are the committed version of the database
// (serialized in big-Endian order). The last 2 bytes are monotonic in the serialization order for
// transactions. WARNING: At this time, versionstamps are compatible with the Tuple layer only in
// the Java, Python, and Go bindings. Also, note that prior to API version 520, the offset was
// computed from only the final two bytes rather than the final four bytes.
// Parameter: value to which to set the transformed key
func (t *Transaction) SetVersionstampedKey(key, param []byte) {
	t.Atomic(MutationTypeSetVersionstampedKey, key, param)
}

// SetVersionstampedValue applies the set_versionstamped_value mutation type to key. Transforms
// param using a versionstamp for the transaction. Sets the key given to the transformed param. The
// parameter is transformed by removing the final four bytes from param and reading those as a
// little-Endian 32-bit integer to get a position pos. The 10 bytes of the parameter from pos to pos
// + 10 are replaced with the versionstamp of the transaction used. The first byte of the parameter
// is position 0. A versionstamp is a 10 byte, unique, monotonically (but not sequentially)
// increasing value for each committed transaction. The first 8 bytes are the committed version of
// the database (serialized in big-Endian order). The last 2 bytes are monotonic in the
// serialization order for transactions. WARNING: At this time, versionstamps are compatible with
// the Tuple layer only in the Java, Python, and Go bindings. Also, note that prior to API version
// 520, the versionstamp was always placed at the beginning of the parameter rather than computing
// an offset.
// Parameter: value to versionstamp and set
func (t *Transaction) SetVersionstampedValue(key, param []byte) {
	t.Atomic(MutationTypeSetVersionstampedValue, key, param)
}

// ByteMin applies the byte_min mutation type to key. Performs lexicographic comparison of byte
// strings. If the existing value in the database is not present, then param is stored. Otherwise
// the smaller of the two values is then stored in the database.
// Parameter: value to check against database value
func (t *Transaction) ByteMin(key, param []byte) {
	t.Atomic(MutationTypeByteMin, key, param)
}

// ByteMax applies the byte_max mutation type to key. Performs lexicographic comparison of byte
// strings. If the existing value in the database is not present, then param is stored. Otherwise
// the larger of the two values is then stored in the database.
// Parameter: value to check against database value
func (t *Transaction) ByteMax(key, param []byte) {
	t.Atomic(MutationTypeByteMax, key, param)
}

// CompareAndClear applies the compare_and_clear mutation type to key. Performs an atomic compare
// and clear operation. If the existing value in the database is equal to the given value, then
// given key is cleared.
// Parameter: Value to compare with
func (t *Transaction) CompareAndClear(key, param []byte) {
	t.Atomic(MutationTypeCompareAndClear, key, param)
}

// ConflictRangeType selects the conflict set a range is added to.
type ConflictRangeType int

// Conflict range types.
const (
	// ConflictRangeTypeRead is the read conflict range type. Used to add a read conflict range
	ConflictRangeTypeRead ConflictRangeType = options.ConflictRangeTypeRead
	// ConflictRangeTypeWrite is the write conflict range type. Used to add a write conflict range
	ConflictRangeTypeWrite ConflictRangeType = options.ConflictRangeTypeWrite
)
